(()=>{if(window.__hsjFixSurgeryActions20261023)return;window.__hsjFixSurgeryActions20261023=true;
const get=id=>document.getElementById(id)?.value?.trim()||'';
const getPatient=id=>S.rows.find(x=>x.id===id);
const phone=x=>{let n=String(x?.phone||'').replace(/\D/g,'');if(n.startsWith('55')&&(n.length===12||n.length===13))n=n.slice(2);return n.length===10||n.length===11?'55'+n:null};
const date=s=>String(s||'').split('-').reverse().join('/');
function effectiveMessage(x){return 'Olá, '+x.patient_name+'!\nAqui é do Setor de Marcação de Cirurgia do Hospital São José.\n\nAgendamento cirúrgico:\nProcedimento: '+(x.procedure_name||'Conforme solicitação')+'\nData: '+date(get('ac_date'))+'\nHorário da cirurgia: '+get('ac_time')+'\nHorário de chegada: '+(get('ac_arrival')||'Conforme orientação da equipe')+'\nLocal: '+get('ac_location')+'\n\nOrientações: '+get('ac_instructions')+'\n\nResponsável pelo agendamento: '+get('ac_by')+'\nPor favor, confirme o recebimento desta mensagem.'}
function missedMessage(x){return 'Olá,\nEste número pertence ao paciente '+x.patient_name+'?\nAqui é do Setor de Marcação de Cirurgia do Hospital São José.\nEstamos tentando entrar em contato por ligação telefonica, mas não estamos conseguindo.\nPoderia nos retornar assim que possível?'}
const originalOpen=window.hsjAgendaSurgery;
window.hsjAgendaSurgery=async function(id){await originalOpen(id);const foot=document.querySelector('#modal .mf');if(!foot)return;foot.querySelectorAll('button').forEach(b=>{if(/Salvar triagem e agendar/i.test(b.textContent)){b.onclick=()=>window.hsjFinishSurgeryWithWhatsApp(id)}else if(/WhatsApp — contato efetivo/i.test(b.textContent)){b.onclick=()=>window.hsjFinishSurgeryWithWhatsApp(id)}else if(/WhatsApp — contato sem sucesso/i.test(b.textContent)){b.onclick=()=>window.hsjMissedContact(id)}})};
window.hsjFinishSurgeryWithWhatsApp=async function(id){const x=getPatient(id);if(!x)return alert('Paciente não localizado');const n=phone(x);const preview=effectiveMessage(x);const a=document.querySelector('#modal .mf button');if(a?.disabled)return;
const popup=n?window.open('about:blank','_blank'):null;
if(a)a.disabled=true;
try{const ok=await window.hsjSaveSurgery(id);if(!ok){if(popup)popup.close();return;}if(popup){popup.location.href='https://wa.me/'+n+'?text='+encodeURIComponent(preview)}else alert('Agendamento realizado, mas o telefone cadastrado não é válido para WhatsApp. Cadastre um número com DDD para enviar o lembrete.');document.getElementById('modal').innerHTML='';S.view='mapa_cirurgico';renderTabs();renderCurrent();}catch(e){if(popup)popup.close();alert('Não foi possível concluir o agendamento: '+e.message)}finally{if(a?.isConnected)a.disabled=false}};
window.hsjMissedContact=async function(id){const x=getPatient(id);if(!x)return alert('Paciente não localizado');const n=phone(x);const popup=n?window.open('about:blank','_blank'):null;const button=[...document.querySelectorAll('#modal .mf button')].find(b=>/contato sem sucesso/i.test(b.textContent));if(button)button.disabled=true;try{await api('/rest/v1/rpc/hsj_registrar_contato_sem_sucesso',{method:'POST',body:JSON.stringify({p_surgery_id:id})});if(popup)popup.location.href='https://wa.me/'+n+'?text='+encodeURIComponent(missedMessage(x));else alert('Tentativa sem sucesso registrada, porém o paciente não possui telefone válido com DDD para WhatsApp.');document.getElementById('modal').innerHTML='';await load();renderCurrent();alert('Contato sem sucesso registrado como PENDENTE. O paciente não foi encaminhado ao Mapa Cirúrgico.')}catch(e){if(popup)popup.close();alert('Não foi possível registrar a tentativa: '+e.message)}finally{if(button?.isConnected)button.disabled=false}};
})();